INSERT OR REPLACE INTO _counters (name, value) VALUES ('weather', 2000);

-- 2026-08 quality repair: historical AQI and hourly observations retain every
-- row but no longer follow simple arithmetic cycles.
UPDATE daily_aqi
SET aqi = max(18, min(180, aqi + CASE (rowid % 13)
      WHEN 0 THEN 9 WHEN 1 THEN -4 WHEN 2 THEN 15 WHEN 3 THEN -11
      WHEN 4 THEN 3 WHEN 5 THEN 18 WHEN 6 THEN -7 WHEN 7 THEN 6
      WHEN 8 THEN -13 WHEN 9 THEN 12 WHEN 10 THEN -2 WHEN 11 THEN 5 ELSE -8 END));
UPDATE daily_aqi
SET category = CASE WHEN aqi <= 50 THEN 'good' WHEN aqi <= 100 THEN 'moderate' ELSE 'sensitive' END;

UPDATE hourly_weather
SET temp_c = round(temp_c + CASE (rowid % 9)
      WHEN 0 THEN 0.3 WHEN 1 THEN -0.2 WHEN 2 THEN 0.1 WHEN 3 THEN -0.4
      WHEN 4 THEN 0.0 WHEN 5 THEN 0.5 WHEN 6 THEN -0.1 WHEN 7 THEN 0.2 ELSE -0.3 END, 1),
    humidity = max(35, min(99, humidity + CASE (rowid % 7)
      WHEN 0 THEN 1 WHEN 1 THEN -2 WHEN 2 THEN 0 WHEN 3 THEN 2
      WHEN 4 THEN -1 WHEN 5 THEN 3 ELSE -3 END)),
    precip_mm = round(max(0, precip_mm + CASE (rowid % 11)
      WHEN 0 THEN 0.1 WHEN 1 THEN -0.1 WHEN 2 THEN 0.0 WHEN 3 THEN 0.2
      WHEN 4 THEN -0.2 WHEN 5 THEN 0.1 WHEN 6 THEN 0.0 WHEN 7 THEN -0.1
      WHEN 8 THEN 0.3 WHEN 9 THEN -0.2 ELSE 0.0 END), 1),
    wind_kmh = max(1, wind_kmh + CASE (rowid % 13)
      WHEN 0 THEN 2 WHEN 1 THEN -1 WHEN 2 THEN 0 WHEN 3 THEN 3
      WHEN 4 THEN -2 WHEN 5 THEN 1 WHEN 6 THEN -3 WHEN 7 THEN 2
      WHEN 8 THEN 0 WHEN 9 THEN -1 WHEN 10 THEN 4 WHEN 11 THEN -2 ELSE 1 END);

-- 2026-08 second-pass manual-cat repair: condition labels agree with their
-- numeric observations instead of following an unrelated row cycle.
UPDATE daily_weather
SET condition = CASE
  WHEN precip_mm >= 10 THEN 'storm'
  WHEN precip_mm >= 3 THEN 'shower'
  WHEN precip_mm >= 0.8 THEN 'drizzle'
  WHEN tmax >= 33 THEN 'hot'
  WHEN wind_kmh >= 25 THEN 'windy'
  WHEN precip_prob >= 0.55 THEN 'cloudy'
  ELSE 'clear' END;

DELETE FROM daily_weather WHERE date > '2026-07-06';
DELETE FROM hourly_weather WHERE datetime > '2026-07-06T09:10:00+08:00';
DELETE FROM alerts WHERE start_dt > '2026-07-06T09:10:00+08:00';
DELETE FROM alert_subscriptions WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM notifications WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM typhoon_tracks WHERE dt > '2026-07-06T09:10:00+08:00';
DELETE FROM daily_aqi WHERE date > '2026-07-06';

DELETE FROM daily_weather WHERE date > '2026-07-06';
DELETE FROM hourly_weather WHERE datetime > '2026-07-06T09:10:00+08:00';
DELETE FROM alerts WHERE start_dt > '2026-07-06T09:10:00+08:00';
DELETE FROM alert_subscriptions WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM notifications WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM typhoon_tracks WHERE dt > '2026-07-06T09:10:00+08:00';
DELETE FROM daily_aqi WHERE date > '2026-07-06';

UPDATE hourly_weather
SET condition = CASE
  WHEN precip_mm >= 2.5 THEN 'storm'
  WHEN precip_mm >= 0.8 THEN 'shower'
  WHEN precip_mm >= 0.2 THEN 'drizzle'
  WHEN temp_c >= 33 THEN 'hot'
  WHEN wind_kmh >= 28 THEN 'windy'
  WHEN humidity >= 88 THEN 'cloudy'
  ELSE 'clear' END;
